/**
 * Signaling for host mode (browser-hosted arenas), deployed as a Vercel Function at /api/p2p.
 *
 * It only introduces browsers to each other: a host registers a room code, a guest posts a WebRTC
 * offer under that code, the host polls for offers and posts answers, the guest polls for its
 * answer. Game traffic never passes through here. Mailboxes live in Redis (Upstash REST API, from
 * the Vercel Storage integration) with short expiries; the dev server and tests use MemoryStore.
 *
 * Deployed as plain JavaScript (api/p2p.js, generated by scripts/build-api.mjs), so it must stay
 * self-contained: no imports. `handleSignal`, `handleHttp` and `MemoryStore` are also used by the
 * Vite dev/preview middleware and the unit tests.
 */

// ------------------------------------------------------------------------------------- constants

/** Same alphabet and length as the dedicated-server room codes (tested against @scrapline/shared). */
export const CODE_ALPHABET = "ABCDEFGHJKMNPQRSTUVWXYZ23456789";
export const CODE_LENGTH = 5;
/** A hosted room's registration lives this long without a host poll (each poll renews it). */
export const ROOM_TTL_SEC = 120;
/** Offers and answers are consumed within seconds; anything older is stale. */
export const MAILBOX_TTL_SEC = 60;
const MAX_PENDING_OFFERS = 16;
const MAX_SDP_CHARS = 24_000;
const MAX_BODY_CHARS = 32_000;
export const OPERATIONS = ["create", "join", "poll", "answer", "wait", "close", "ice"] as const;
/**
 * Per client address and minute, for the operations that create state or call out. Schools put a
 * whole class behind one public address, hence the generous numbers. The others need the host key
 * or an unguessable guest id, and are not counted (each count costs Redis commands).
 */
export const RATE_LIMITS: Record<string, number> = { create: 30, join: 120, ice: 120 };

// ------------------------------------------------------------------------------------- storage

export interface SignalStore {
  /** SET key value EX ttl NX. True when the key was created. */
  setNx(key: string, value: string, ttlSec: number): Promise<boolean>;
  get(key: string): Promise<string | null>;
  set(key: string, value: string, ttlSec: number): Promise<void>;
  getDel(key: string): Promise<string | null>;
  del(...keys: string[]): Promise<void>;
  expire(key: string, ttlSec: number): Promise<void>;
  /** Appends to a list, keeps its newest `max` items and sets its expiry. Returns the length. */
  push(key: string, value: string, max: number, ttlSec: number): Promise<number>;
  /** Removes and returns up to `count` items from the head of a list, and renews another key. */
  popAndRenew(key: string, count: number, renewKey: string, ttlSec: number): Promise<string[]>;
  /** INCR with an expiry. */
  incr(key: string, ttlSec: number): Promise<number>;
}

/** In-process store for the dev server and tests (Redis semantics, lazy expiry). */
export class MemoryStore implements SignalStore {
  private readonly data = new Map<string, { v: string | string[] | number; exp: number }>();
  constructor(private readonly now: () => number = Date.now) {}

  private live(key: string) {
    const e = this.data.get(key);
    if (!e) return undefined;
    if (e.exp <= this.now()) {
      this.data.delete(key);
      return undefined;
    }
    return e;
  }
  async setNx(key: string, value: string, ttlSec: number) {
    if (this.live(key)) return false;
    this.data.set(key, { v: value, exp: this.now() + ttlSec * 1000 });
    return true;
  }
  async get(key: string) {
    const e = this.live(key);
    return typeof e?.v === "string" ? e.v : null;
  }
  async set(key: string, value: string, ttlSec: number) {
    this.data.set(key, { v: value, exp: this.now() + ttlSec * 1000 });
  }
  async getDel(key: string) {
    const v = await this.get(key);
    this.data.delete(key);
    return v;
  }
  async del(...keys: string[]) {
    for (const k of keys) this.data.delete(k);
  }
  async expire(key: string, ttlSec: number) {
    const e = this.live(key);
    if (e) e.exp = this.now() + ttlSec * 1000;
  }
  async push(key: string, value: string, max: number, ttlSec: number) {
    const e = this.live(key);
    const list = Array.isArray(e?.v) ? e.v : [];
    list.push(value);
    while (list.length > max) list.shift();
    this.data.set(key, { v: list, exp: this.now() + ttlSec * 1000 });
    return list.length;
  }
  async popAndRenew(key: string, count: number, renewKey: string, ttlSec: number) {
    await this.expire(renewKey, ttlSec);
    const e = this.live(key);
    if (!e || !Array.isArray(e.v)) return [];
    const out = e.v.splice(0, count);
    if (e.v.length === 0) this.data.delete(key);
    return out;
  }
  async incr(key: string, ttlSec: number) {
    const e = this.live(key);
    const n = (typeof e?.v === "number" ? e.v : 0) + 1;
    this.data.set(key, { v: n, exp: e ? e.exp : this.now() + ttlSec * 1000 });
    return n;
  }
}

/** Upstash Redis over its REST API (no client library needed). */
export class UpstashStore implements SignalStore {
  constructor(
    private readonly url: string,
    private readonly token: string,
    private readonly fetchImpl: typeof fetch = fetch,
  ) {}

  private async pipeline(commands: (string | number)[][]): Promise<unknown[]> {
    const res = await this.fetchImpl(`${this.url}/pipeline`, {
      method: "POST",
      headers: { Authorization: `Bearer ${this.token}`, "Content-Type": "application/json" },
      body: JSON.stringify(commands),
    });
    if (!res.ok) throw new StoreError(`redis http ${res.status}`);
    const out = (await res.json()) as { result?: unknown; error?: string }[];
    return out.map((r) => {
      if (r.error) throw new StoreError(`redis: ${r.error}`);
      return r.result;
    });
  }
  async setNx(key: string, value: string, ttlSec: number) {
    const [r] = await this.pipeline([["SET", key, value, "EX", ttlSec, "NX"]]);
    return r === "OK";
  }
  async get(key: string) {
    const [r] = await this.pipeline([["GET", key]]);
    return typeof r === "string" ? r : null;
  }
  async set(key: string, value: string, ttlSec: number) {
    await this.pipeline([["SET", key, value, "EX", ttlSec]]);
  }
  async getDel(key: string) {
    const [r] = await this.pipeline([["GETDEL", key]]);
    return typeof r === "string" ? r : null;
  }
  async del(...keys: string[]) {
    if (keys.length > 0) await this.pipeline([["DEL", ...keys]]);
  }
  async expire(key: string, ttlSec: number) {
    await this.pipeline([["EXPIRE", key, ttlSec]]);
  }
  async push(key: string, value: string, max: number, ttlSec: number) {
    const [n] = await this.pipeline([
      ["RPUSH", key, value],
      ["LTRIM", key, -max, -1],
      ["EXPIRE", key, ttlSec],
    ]);
    return Math.min(Number(n), max);
  }
  async popAndRenew(key: string, count: number, renewKey: string, ttlSec: number) {
    const [r] = await this.pipeline([
      ["LPOP", key, count],
      ["EXPIRE", renewKey, ttlSec],
    ]);
    return Array.isArray(r) ? r.filter((x): x is string => typeof x === "string") : [];
  }
  async incr(key: string, ttlSec: number) {
    const [n] = await this.pipeline([
      ["INCR", key],
      ["EXPIRE", key, ttlSec],
    ]);
    return Number(n);
  }
}

export class StoreError extends Error {}

type Env = Record<string, string | undefined>;

/**
 * Finds Upstash REST credentials in the environment. The Vercel Storage integration names them
 * KV_REST_API_URL / KV_REST_API_TOKEN (with an optional custom prefix); Upstash's own integration
 * uses UPSTASH_REDIS_REST_URL / UPSTASH_REDIS_REST_TOKEN. As a last resort an Upstash Redis URL
 * (rediss://default:<token>@<host>:6379) is converted: its password is the REST token.
 */
export function upstashFromEnv(env: Env): { url: string; token: string } | null {
  const pairs: [string, string][] = [
    ["KV_REST_API_URL", "KV_REST_API_TOKEN"],
    ["UPSTASH_REDIS_REST_URL", "UPSTASH_REDIS_REST_TOKEN"],
  ];
  for (const key of Object.keys(env).sort()) {
    for (const suffix of ["_KV_REST_API_URL", "_UPSTASH_REDIS_REST_URL"]) {
      if (key.endsWith(suffix) && key !== suffix.slice(1)) {
        pairs.push([key, key.replace(/_URL$/, "_TOKEN")]);
      }
    }
  }
  for (const [u, t] of pairs) {
    const url = env[u];
    const token = env[t];
    if (url && token) return { url: url.replace(/\/$/, ""), token };
  }
  for (const key of ["KV_URL", "REDIS_URL", "UPSTASH_REDIS_URL"]) {
    const raw = env[key];
    if (!raw) continue;
    try {
      const u = new URL(raw);
      if (u.hostname.endsWith(".upstash.io") && u.password) {
        return { url: `https://${u.hostname}`, token: decodeURIComponent(u.password) };
      }
    } catch {
      // not a URL
    }
  }
  return null;
}

// ------------------------------------------------------------------------------------- ICE

export interface IceServer {
  urls: string | string[];
  username?: string;
  credential?: string;
}

/** Public STUN servers: enough when the two browsers can reach each other directly. */
export const DEFAULT_STUN: IceServer[] = [
  { urls: ["stun:stun.cloudflare.com:3478", "stun:stun.l.google.com:19302"] },
];

/**
 * TURN relays for networks that block direct connections (common in schools). Either static
 * credentials (TURN_URLS comma separated, TURN_USERNAME, TURN_CREDENTIAL) or Cloudflare Realtime
 * TURN short-lived credentials (CLOUDFLARE_TURN_KEY_ID, CLOUDFLARE_TURN_API_TOKEN).
 */
export async function iceServersFromEnv(env: Env, fetchImpl: typeof fetch = fetch): Promise<IceServer[]> {
  return (await iceConfig(env, fetchImpl)).servers;
}

function cleanSecret(v: string | undefined): string {
  return (v ?? "")
    .trim()
    .replace(/^["']|["']$/g, "")
    .trim();
}

/**
 * Shape of the configured TURN key id, for the health endpoint (an id, not a secret: it is part
 * of the request URL). Cloudflare TURN key ids are 32 hexadecimal characters.
 */
export function turnKeyShape(env: Env): { length: number; hex32: boolean; cleaned: boolean } | null {
  const raw = env.CLOUDFLARE_TURN_KEY_ID;
  if (!raw) return null;
  const id = cleanSecret(raw);
  return { length: id.length, hex32: /^[0-9a-f]{32}$/i.test(id), cleaned: id !== raw };
}

/**
 * Relay availability without secrets, for the health endpoint: "none" (STUN only), "static"
 * (TURN_URLS), "cloudflare" (credentials issued), "cloudflare-error:<status>" or
 * "cloudflare-unreachable". A misconfigured relay used to fall back to STUN silently.
 */
export type TurnStatus = string;

export async function iceConfig(
  env: Env,
  fetchImpl: typeof fetch = fetch,
): Promise<{ servers: IceServer[]; turn: TurnStatus }> {
  const servers: IceServer[] = [...DEFAULT_STUN];
  let turn: TurnStatus = "none";
  if (env.TURN_URLS) {
    servers.push({
      urls: env.TURN_URLS.split(",")
        .map((s) => s.trim())
        .filter(Boolean),
      ...(env.TURN_USERNAME ? { username: env.TURN_USERNAME } : {}),
      ...(env.TURN_CREDENTIAL ? { credential: env.TURN_CREDENTIAL } : {}),
    });
    turn = "static";
  }
  // Values pasted into a dashboard often carry a space, a newline or quotes: strip them.
  const keyId = cleanSecret(env.CLOUDFLARE_TURN_KEY_ID);
  const apiToken = cleanSecret(env.CLOUDFLARE_TURN_API_TOKEN);
  if (keyId && apiToken) {
    try {
      const res = await fetchImpl(
        `https://rtc.live.cloudflare.com/v1/turn/keys/${encodeURIComponent(keyId)}/credentials/generate-ice-servers`,
        {
          method: "POST",
          headers: {
            Authorization: `Bearer ${apiToken}`,
            "Content-Type": "application/json",
          },
          body: JSON.stringify({ ttl: 6 * 3600 }),
        },
      );
      if (res.ok) {
        const body = (await res.json()) as { iceServers?: IceServer | IceServer[] };
        const list = Array.isArray(body.iceServers)
          ? body.iceServers
          : body.iceServers
            ? [body.iceServers]
            : [];
        // Only the relays: STUN is already listed above.
        let added = 0;
        for (const s of list) {
          const urls = (Array.isArray(s.urls) ? s.urls : [s.urls]).filter((u) => /^turns?:/.test(u));
          if (urls.length > 0) {
            servers.push({ ...s, urls });
            added++;
          }
        }
        turn = added > 0 ? "cloudflare" : "cloudflare-error:no-relays";
      } else {
        turn = `cloudflare-error:${res.status}`;
        console.warn(`[p2p] Cloudflare TURN credentials refused: HTTP ${res.status}`);
      }
    } catch {
      // TURN is optional: direct connections still work on most networks.
      turn = "cloudflare-unreachable";
      console.warn("[p2p] Cloudflare TURN unreachable");
    }
  }
  return { servers, turn };
}

// ------------------------------------------------------------------------------------- handler

export interface SignalRequest {
  op: string;
  body: unknown;
  /** Client address, for rate limits. */
  ip: string;
}

export interface SignalResponse {
  status: number;
  body: Record<string, unknown>;
}

export interface SignalDeps {
  store: SignalStore;
  env?: Env;
  random?: (bytes: number) => Uint8Array;
  now?: () => number;
  fetchImpl?: typeof fetch;
}

const ok = (body: Record<string, unknown>): SignalResponse => ({ status: 200, body });
const fail = (status: number, error: string): SignalResponse => ({ status, body: { error } });

function defaultRandom(n: number): Uint8Array {
  const b = new Uint8Array(n);
  crypto.getRandomValues(b);
  return b;
}

function base64url(bytes: Uint8Array): string {
  let s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  return btoa(s).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");
}

async function sha256(text: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return base64url(new Uint8Array(digest));
}

/** Uniform random code (rejection sampling, no modulo bias). */
function randomCode(random: (n: number) => Uint8Array): string {
  const limit = 256 - (256 % CODE_ALPHABET.length);
  let out = "";
  while (out.length < CODE_LENGTH) {
    for (const b of random(16)) {
      if (b < limit && out.length < CODE_LENGTH) out += CODE_ALPHABET[b % CODE_ALPHABET.length];
    }
  }
  return out;
}

const isCode = (v: unknown): v is string =>
  typeof v === "string" && v.length === CODE_LENGTH && [...v].every((c) => CODE_ALPHABET.includes(c));
const isToken = (v: unknown): v is string => typeof v === "string" && /^[A-Za-z0-9_-]{16,64}$/.test(v);
const isSdp = (v: unknown): v is string =>
  typeof v === "string" && v.length > 10 && v.length <= MAX_SDP_CHARS && v.startsWith("v=0");

const roomKey = (code: string) => `p2p:room:${code}`;
const inboxKey = (code: string) => `p2p:in:${code}`;
const answerKey = (guestId: string) => `p2p:ans:${guestId}`;

interface RoomRecord {
  /** SHA-256 of the host key: a leaked Redis dump does not let anyone impersonate the host. */
  h: string;
  t: number;
}

export async function handleSignal(req: SignalRequest, deps: SignalDeps): Promise<SignalResponse> {
  const { store } = deps;
  const random = deps.random ?? defaultRandom;
  const now = deps.now ?? Date.now;
  if (!(OPERATIONS as readonly string[]).includes(req.op)) return fail(404, "unknown operation");
  const body = (req.body && typeof req.body === "object" ? req.body : {}) as Record<string, unknown>;

  const limit = RATE_LIMITS[req.op];
  if (limit !== undefined) {
    const minute = Math.floor(now() / 60_000);
    const hits = await store.incr(`p2p:rl:${req.op}:${req.ip}:${minute}`, 70);
    if (hits > limit) return fail(429, "too many requests, try again in a minute");
  }

  const verifyHost = async (): Promise<RoomRecord | SignalResponse> => {
    if (!isCode(body.code) || !isToken(body.hostKey)) return fail(400, "invalid request");
    const raw = await store.get(roomKey(body.code));
    if (!raw) return fail(404, "room not found");
    const rec = JSON.parse(raw) as RoomRecord;
    if (rec.h !== (await sha256(body.hostKey))) return fail(403, "not the host of this room");
    return rec;
  };

  switch (req.op) {
    case "create": {
      const hostKey = base64url(random(32));
      const record: RoomRecord = { h: await sha256(hostKey), t: now() };
      for (let attempt = 0; attempt < 10; attempt++) {
        const code = randomCode(random);
        if (await store.setNx(roomKey(code), JSON.stringify(record), ROOM_TTL_SEC)) {
          return ok({ code, hostKey, ttlSec: ROOM_TTL_SEC });
        }
      }
      return fail(503, "no free room code, try again");
    }
    case "join": {
      if (!isCode(body.code) || !isSdp(body.sdp)) return fail(400, "invalid request");
      if (body.resume !== undefined && !isToken(body.resume)) return fail(400, "invalid request");
      if (!(await store.get(roomKey(body.code)))) return fail(404, "room not found");
      const guestId = base64url(random(18));
      const offer = { g: guestId, sdp: body.sdp, ...(body.resume ? { r: body.resume } : {}) };
      await store.push(inboxKey(body.code), JSON.stringify(offer), MAX_PENDING_OFFERS, MAILBOX_TTL_SEC);
      return ok({ guestId });
    }
    case "poll": {
      const v = await verifyHost();
      if ("status" in v) return v;
      const code = body.code as string;
      const raw = await store.popAndRenew(inboxKey(code), MAX_PENDING_OFFERS, roomKey(code), ROOM_TTL_SEC);
      const offers = raw.flatMap((s) => {
        try {
          const o = JSON.parse(s) as { g: string; sdp: string; r?: string };
          return [{ guestId: o.g, sdp: o.sdp, ...(o.r ? { resume: o.r } : {}) }];
        } catch {
          return [];
        }
      });
      return ok({ offers, ttlSec: ROOM_TTL_SEC });
    }
    case "answer": {
      const v = await verifyHost();
      if ("status" in v) return v;
      if (!isToken(body.guestId)) return fail(400, "invalid request");
      const hasSdp = isSdp(body.sdp);
      const reason = typeof body.error === "string" ? body.error.slice(0, 200) : null;
      if (!hasSdp && !reason) return fail(400, "invalid request");
      const value = hasSdp ? { sdp: body.sdp } : { error: reason };
      await store.set(answerKey(body.guestId), JSON.stringify(value), MAILBOX_TTL_SEC);
      return ok({});
    }
    case "wait": {
      if (!isToken(body.guestId)) return fail(400, "invalid request");
      const raw = await store.getDel(answerKey(body.guestId));
      return ok({ answer: raw ? (JSON.parse(raw) as Record<string, unknown>) : null });
    }
    case "close": {
      const v = await verifyHost();
      if ("status" in v) return v;
      await store.del(roomKey(body.code as string), inboxKey(body.code as string));
      return ok({});
    }
    case "ice":
      return ok({ iceServers: await iceServersFromEnv(deps.env ?? {}, deps.fetchImpl) });
  }
  return fail(404, "unknown operation");
}

// ------------------------------------------------------------------------------------- HTTP

const JSON_HEADERS = { "Content-Type": "application/json", "Cache-Control": "no-store" };

/** Shared by the Vercel entry and the Vite dev middleware. */
export async function handleHttp(
  request: Request,
  deps: Omit<SignalDeps, "store"> & { store: SignalStore | null },
): Promise<Response> {
  if (request.method === "GET") {
    // Health/diagnostics: is the Redis store configured and answering? (No secrets in the reply.)
    let storage = "missing";
    if (deps.store) {
      try {
        await deps.store.get("p2p:health");
        storage = "connected";
      } catch {
        storage = "unreachable";
      }
    }
    // Relay status (no credentials in the reply): tells "not configured" from "refused".
    const { turn } = await iceConfig(deps.env ?? {}, deps.fetchImpl);
    const turnKey = turnKeyShape(deps.env ?? {});
    return new Response(
      JSON.stringify({ service: "scrapline-signaling", storage, turn, ...(turnKey ? { turnKey } : {}) }),
      { status: 200, headers: JSON_HEADERS },
    );
  }
  if (request.method !== "POST") {
    return new Response(JSON.stringify({ error: "method not allowed" }), {
      status: 405,
      headers: JSON_HEADERS,
    });
  }
  if (!deps.store) {
    return new Response(
      JSON.stringify({
        error: "Host mode is not configured: connect an Upstash Redis store to this Vercel project.",
      }),
      { status: 503, headers: JSON_HEADERS },
    );
  }
  const op = new URL(request.url).searchParams.get("op") ?? "";
  const text = await request.text();
  if (text.length > MAX_BODY_CHARS) {
    return new Response(JSON.stringify({ error: "request too large" }), {
      status: 413,
      headers: JSON_HEADERS,
    });
  }
  let body: unknown = {};
  try {
    body = text ? JSON.parse(text) : {};
  } catch {
    return new Response(JSON.stringify({ error: "invalid JSON" }), { status: 400, headers: JSON_HEADERS });
  }
  const ip =
    request.headers.get("x-real-ip") ??
    request.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ??
    "local";
  try {
    const res = await handleSignal({ op, body, ip }, { ...deps, store: deps.store });
    return new Response(JSON.stringify(res.body), { status: res.status, headers: JSON_HEADERS });
  } catch (err) {
    console.error("signal error", err instanceof Error ? err.message : err);
    return new Response(JSON.stringify({ error: "signaling storage unavailable" }), {
      status: 503,
      headers: JSON_HEADERS,
    });
  }
}

const processEnv = (): Env => (globalThis as unknown as { process?: { env: Env } }).process?.env ?? {};

let cachedStore: SignalStore | null | undefined;

export default {
  async fetch(request: Request): Promise<Response> {
    const env = processEnv();
    if (cachedStore === undefined) {
      const creds = upstashFromEnv(env);
      cachedStore = creds ? new UpstashStore(creds.url, creds.token) : null;
    }
    return handleHttp(request, { store: cachedStore, env });
  },
};
